<?php
require __DIR__.'/bootstrap.php'; require __DIR__.'/lib/CareView.php';
$auth->requireAbility('finance'); $church=$auth->currentChurch(); if(!$church) redirect('/logout.php');
$care=new ChurchCare($pdo,(string)$church['id']); $error=null; $edit=[]; $selected=trim((string)($_GET['asset']??''));
if($_SERVER['REQUEST_METHOD']==='POST') {
    csrf_check(); try {
        if(($_POST['action']??'')==='maintenance') { $care->maintenance($_POST); $selected=ChurchCare::text($_POST,'asset_id',36,true); }
        else $selected=$care->asset($_POST);
        flash('success','Patrimônio atualizado.'); redirect('/assets.php?asset='.rawurlencode($selected));
    } catch(Throwable $e) { $error=care_error($e); }
}
if($selected!=='') { try { $edit=$care->owned('church_assets',$selected); } catch(Throwable $e) { $error=care_error($e); $selected=''; } }
$q=trim((string)($_GET['q']??'')); $status=(string)($_GET['status']??'all');
$sql='SELECT * FROM church_assets WHERE church_id=?'; $params=[];
if($q!=='') { $sql.=' AND (name LIKE ? OR code LIKE ? OR location LIKE ? OR category LIKE ?)'; $params=array_fill(0,4,'%'.$q.'%'); }
if(isset(ChurchCare::ASSET_STATUS[$status])) { $sql.=' AND status=?'; $params[]=$status; }
if(isset($_GET['due'])) $sql.=" AND status<>'retired' AND (SELECT h.next_due FROM asset_maintenance h WHERE h.asset_id=church_assets.id AND h.church_id=church_assets.church_id ORDER BY h.performed_on DESC,h.created_at DESC,h.id DESC LIMIT 1)<=CURDATE()";
$rows=$care->all($sql.' ORDER BY name LIMIT 500',$params);
$totals=$care->all("SELECT COUNT(*) total,COALESCE(SUM(acquisition_value),0) value FROM church_assets WHERE church_id=? AND status<>'retired'")[0];
$history=$selected!==''?$care->all('SELECT * FROM asset_maintenance WHERE church_id=? AND asset_id=? ORDER BY performed_on DESC,created_at DESC',[$selected]):[];
View::header('Patrimônio',$auth,'assets.php'); care_heading('Patrimônio e manutenção','Controle bens, localização, responsáveis e histórico de manutenção sem alterar o caixa automaticamente.'); care_notice($error);
?>
<div class="grid stats"><div class="card stat"><div class="stat-label">Bens em uso ou manutenção</div><div class="stat-value"><?=(int)$totals['total']?></div></div><div class="card stat"><div class="stat-label">Valor de aquisição desses bens</div><div class="stat-value">R$ <?=number_format((float)$totals['value'],2,',','.')?></div></div></div>
<div class="grid two-col"><section class="card card-pad"><form class="toolbar no-print" method="get"><input class="input" name="q" value="<?=e($q)?>" placeholder="Nome, código, categoria ou local" aria-label="Buscar bem"><select class="select" name="status" aria-label="Condição"><option value="all">Todas as condições</option><?php foreach(ChurchCare::ASSET_STATUS as $k=>$v):?><option value="<?=e($k)?>" <?=$k===$status?'selected':''?>><?=e($v)?></option><?php endforeach?></select><label><input type="checkbox" name="due" value="1" <?=isset($_GET['due'])?'checked':''?>> Manutenção até hoje</label><button class="btn btn-light">Filtrar</button></form><p class="muted"><?=count($rows)?> bem(ns), até 500 por consulta.</p><div class="table-wrap"><table class="table"><thead><tr><th>Bem</th><th>Local</th><th>Valor de aquisição</th><th>Condição</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="4">Nenhum bem cadastrado neste filtro.</td></tr><?php endif?><?php foreach($rows as $r):?><tr><td><a href="?asset=<?=e($r['id'])?>"><?=e($r['name'])?></a><div><?=e($r['code'])?> · <?=e($r['category'])?></div></td><td><?=e($r['location'])?><div><?=e($r['responsible'])?></div></td><td>R$ <?=number_format((float)$r['acquisition_value'],2,',','.')?></td><td><?=e(ChurchCare::ASSET_STATUS[$r['status']]??$r['status'])?></td></tr><?php endforeach?></tbody></table></div>
<?php if($edit):?><h2>Manutenções · <?=e($edit['name'])?></h2><?php if(!$history):?><p>Nenhuma manutenção registrada.</p><?php endif?><?php foreach($history as $h):?><article class="care-entry"><strong><?=e(ChurchCare::displayDate($h['performed_on']))?> · R$ <?=number_format((float)$h['cost'],2,',','.')?></strong><p><?=nl2br(e($h['description']))?></p><p><?=e($h['responsible'])?> · Próxima: <?=e(ChurchCare::displayDate($h['next_due']))?></p></article><?php endforeach?><form data-registry-form="asset-maintenance" method="post" class="no-print"><?=csrf_field()?><input type="hidden" name="action" value="maintenance"><input type="hidden" name="asset_id" value="<?=e($selected)?>"><h3>Registrar manutenção</h3><div class="form-grid"><?php care_field('performed_on','Data',date('Y-m-d'),'date',true); care_field('next_due','Próxima manutenção','','date'); care_field('cost','Custo (R$)','0','number',true); care_field('responsible','Responsável'); care_field('description','Serviço realizado','','textarea',true);?></div><button class="btn btn-primary">Salvar manutenção</button><p class="muted">Para contabilizar o pagamento, lance a despesa na Tesouraria.</p></form><?php endif?></section>
<section data-registry-form="assets" class="card card-pad no-print"><h2><?=$edit?'Editar bem':'Novo bem'?></h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-grid"><?php care_field('code','Código / etiqueta',$edit['code']??'','text',true); care_field('name','Nome do bem',$edit['name']??'','text',true); care_field('category','Categoria',$edit['category']??''); care_field('location','Localização',$edit['location']??''); care_field('responsible','Responsável',$edit['responsible']??''); care_field('acquired_on','Data de aquisição',$edit['acquired_on']??'','date'); care_field('acquisition_value','Valor de aquisição (R$)',$edit['acquisition_value']??'0','number',true); care_field('status','Condição',$edit['status']??'good','select',true,ChurchCare::ASSET_STATUS); care_field('notes','Observações',$edit['notes']??'','textarea');?></div><button class="btn btn-primary">Salvar bem</button> <a class="btn btn-light" href="assets.php">Novo / limpar</a></form></section></div>
<?php View::footer();
